def dados_gif_dashboard():
    """Reconstrói o GIF sem escrever arquivos na instalação do usuário."""
    return base64.b64decode(_GIF_BASE64)


class FundoGifDashboard:
    """Reproduz o fundo somente quando o Dashboard está efetivamente visível."""

    def __init__(self, canvas):
        self.canvas = canvas
        self.buffer = None
        self.movie = None
        self.ativo = False
        try:
            self.buffer = QBuffer(canvas)
            self.buffer.setData(QByteArray(dados_gif_dashboard()))
            if not self.buffer.open(QIODevice.ReadOnly):
                return
            self.movie = QMovie(self.buffer, QByteArray(b"gif"), canvas)
            self.movie.setCacheMode(QMovie.CacheMode.CacheNone)
            if not self.movie.isValid():
                self.movie = None
                return
            self.movie.frameChanged.connect(self._quadro_alterado)
            # Primeiro quadro disponível sem disparar animação na tela inicial.
            self.movie.start()
            self.movie.setPaused(True)
        except Exception:
            # Falha de codec/recurso => manter o fundo JPG original do Vighna.
            self.movie = None

    def _quadro_alterado(self, _indice):
        if self.ativo:
            self.canvas.update()

    def quadro(self):
        if self.movie is None:
            return None
        imagem = self.movie.currentPixmap()
        return imagem if not imagem.isNull() else None

    def sincronizar(self, visivel, tema):
        """A preferência de redução de movimento já usada na Home vale aqui."""
        ambiente = os.environ.get("VIGHNA_HOME_REDUZIR_MOVIMENTO", "").strip().lower()
        bloqueio_ambiente = ambiente in ("1", "true", "sim", "yes", "on")
        preferencia = QSettings("VighnaStudy", "Home").value(
            "acessibilidade/reduzir_movimento", False, type=bool
        )
        reproduzir = bool(visivel and tema in ("futurista", "escuro")
                          and not preferencia and not bloqueio_ambiente)
        self.ativo = bool(visivel and tema in ("futurista", "escuro"))
        if self.movie is None:
            return
        try:
            if reproduzir:
                if self.movie.state() == QMovie.MovieState.NotRunning:
                    self.movie.start()
                elif self.movie.state() == QMovie.MovieState.Paused:
                    self.movie.setPaused(False)
            elif self.movie.state() == QMovie.MovieState.Running:
                self.movie.setPaused(True)
            self.canvas.update()
        except Exception:
            self.movie = None
